import * as vscode from 'vscode';
import crypto from 'crypto';
import path from 'path';
import { createPatch } from 'diff';

const snapshots = new Map();
const timers = new Map();

function shouldIgnore(fileName) {
  return (
    fileName.includes(`${path.sep}node_modules${path.sep}`) ||
    fileName.includes(`${path.sep}dist${path.sep}`) ||
    fileName.endsWith('.lock') ||
    fileName.endsWith('.map')
  );
}

function countChangedLines(patch) {
  return patch
    .split('\n')
    .filter(
      line =>
        (line.startsWith('+') || line.startsWith('-')) &&
        !line.startsWith('+++') &&
        !line.startsWith('---')
    ).length;
}

function escapeHtml(value) {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function makeAvatar(name) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map(part => part[0]?.toUpperCase() || '')
    .join('');
}

function buildEditorLines(document) {
  if (!document) {
    return [];
  }

  return document
    .getText()
    .split(/\r?\n/)
    .slice(0, 21)
    .map((text, index) => ({
      number: index + 1,
      text,
    }));
}

function buildFileTree(document) {
  const relative = document
    ? vscode.workspace.asRelativePath(document.uri, false)
    : 'src/auth.ts';
  const segments = relative.split(/[\\/]/).filter(Boolean);
  const items = [];

  if (segments.length === 0) {
    return ['src/', '  auth.ts', '  rateLimiter.ts', '  middleware.ts'];
  }

  if (segments.length > 1) {
    items.push(`${segments[0]}/`);
    for (const segment of segments.slice(1)) {
      items.push(`  ${segment}`);
    }
  } else {
    items.push('src/');
    items.push(`  ${segments[0]}`);
  }

  items.push('  rateLimiter.ts');
  items.push('  middleware.ts');
  items.push('tests/');
  items.push('  auth.test.ts');
  return [...new Set(items)];
}

