     ts: new Date().toISOString(),
     label,
     source: payload.eventType || label,
     ...payload,
   });

   const backendUrl = getConfig("backendUrl");
   if (!backendUrl) {
     return;
   }

   try {
     await fetch(backendUrl, {
       method: "POST",
       headers: {
         "Content-Type": "application/json",
       },
       body: JSON.stringify({
         ...payload,
         userAgent: "vscode-extension",
       }),
