   if (pendingTool && Date.now() - pendingToolTime < TOOL_WINDOW_MS) {
     return pendingTool;
   }

   if (hadRecentCopilotLogActivity()) {
     return "Copilot (log activity)";
   }

   return "Human / Unknown";
 }

 function clearPendingTool() {
   pendingTool = null;
   pendingToolTime = 0;
 }

