   const scheme = String(document?.uri?.scheme || "");

   return (
     scheme === "output" ||
     scheme === "extension-output" ||
     fileName.includes("Commit Confessional") ||
     uriString.includes("Commit Confessional") ||
     uriString.includes("extension-output") ||
     fileName.endsWith(".log")
